/* Morale is situational; temporary effects never overwrite base ratings. */
function personality(p){return {loyalty:25+(p.id*37+17)%71,ambition:25+(p.id*23+41)%71,financial:25+(p.id*19+7)%71}}
function expectedPlayerRole(p){return p.ovr>=85?['Star',36]:p.ovr>=78?['Starter',30]:p.ovr>=72?['Sixth man',22]:p.age<=23?['Prospect',10]:['Rotation',14]}
function defaultMinutes(club,p){const available=club.roster.filter(q=>!injuryDays(q)),starters=available.slice(0,5),bench=available.slice(5).filter(q=>q.ovr>=70).slice(0,4);for(const q of available.slice(5))if(bench.length<Math.min(4,available.length-5)&&!bench.includes(q))bench.push(q);if(available.length===6)return available.includes(p)?40:0;if(starters.includes(p))return bench.length?34:48;const i=bench.indexOf(p);return i<0?0:Math.floor(70/bench.length)+(i<70%bench.length?1:0)}
function rotationValid(club){return club.roster.every(p=>Number.isInteger(p.rotationMinutes)&&p.rotationMinutes>=0&&p.rotationMinutes<=48)&&club.roster.reduce((s,p)=>s+p.rotationMinutes,0)===240}
function playerMinutes(p,club){return club?(rotationValid(club)?p.rotationMinutes:defaultMinutes(club,p)):0}
function resetRotation(club){for(const p of club.roster)p.rotationMinutes=defaultMinutes(club,p)}
function moraleStamp(){return state.year*200+state.day}
moraleDetails=function(p,club){const traits=personality(p),[role,expected]=expectedPlayerRole(p),minutes=playerMinutes(p,club),games=club?club.w+club.l:0;const pct=games?club.w/games:.5;const roleImpact=club?Math.max(-48,Math.min(10,(minutes-expected)*(.9+traits.ambition/100))):-18;const winning=(pct-.5)*(20+traits.ambition*.16)*(pct<.5?1-traits.loyalty/180:1);const market=wnbaEnabled()?wnbaMillions(wnbaDemandDollars(p,club||team(),state.year)):Math.max(1,(p.ovr-56)*.53),underpaid=Math.max(0,(market-p.salary)/market);const contract=-Math.min(22,underpaid*(20+traits.financial*.2));const security=club&&p.contractThrough>=state.year+1?7:0,change=p.moraleAdjustment||0;const happiness=clampMorale(68+winning+roleImpact*.7+change),focus=clampMorale(70+winning*.6+roleImpact*.5+change*.5),satisfaction=clampMorale(68+roleImpact+contract+security+change);const score=clampMorale((happiness+focus+satisfaction)/3);return {score,happiness,focus,satisfaction,label:score>=80?'Thriving':score>=65?'Content':score>=45?'Unsettled':'Unhappy',reasons:[club?`${role} expectations: ${minutes} minutes allocated / ${expected} expected`:'Searching for a team',games?(pct>.5?'Winning record lifts spirits':pct<.5?'Losing record weighs on morale':'Team results are balanced'):'A fresh season',underpaid>.1?'Feels underpaid for current ability':security?'Longer contract provides security':'Contract pay is broadly in line with ability',traits.ambition>=65?'Ambitious: minutes and winning matter more':traits.loyalty>=65?'Loyal: more patient through losses':'Balanced personality',...(p.tradeDemand&&(!p.dissatisfaction||p.dissatisfaction.active?.visibility==='public'||club?.id===controlledTeamId())?['Has requested a trade']:[]),...(change?[`Recent events: ${change>0?'+':''}${change} temporary mood`]:[])]}}
function moraleBonus(score){return score>=80?2:score>=65?1:score>=45?0:score>=30?-4:-8}
function teamChemistry(club){const score=Math.round(club.roster.reduce((s,p)=>s+moraleDetails(p,club).score,0)/club.roster.length);return {score,modifier:score>=80?1:score<45?-3:score<55?-1:0}}
function negotiationStatus(p){const c=playerContext(p.id),m=moraleDetails(p,c?.club).score;return {refuses:m<30||(p.tradeDemand&&m<45),premium:m<45?.30:m<60?.15:.05,score:m}}
extensionQuote=function(p){return Math.round(p.salary*(1+negotiationStatus(p).premium)*10)/10};
const moraleBaseOverview=moraleProfile;
moraleProfile=function(ctx){const m=moraleDetails(ctx.p,ctx.club),traits=personality(ctx.p),bonus=moraleBonus(m.score);return moraleBaseOverview(ctx)+playerCard('MORALE EFFECTS',`<p><strong>${bonus>=0?'+':''}${bonus} temporary skill modifier</strong> · ${ctx.club?'Team chemistry: '+teamChemistry(ctx.club).score+'/100':'No team chemistry'}</p><p>Loyalty ${traits.loyalty} · Ambition ${traits.ambition} · Financial focus ${traits.financial}</p><p>${ctx.p.lowMoraleGames||0} consecutive games of low morale. Trade requests depend on sustained circumstances and individual decisions.</p>${ctx.own?`<button onclick="holdMoraleMeeting(${ctx.p.id})" ${moraleStamp()-(ctx.p.lastTalk??-10000000)<7?'disabled':''}>Coach conversation</button><p>Player relations: ${coachingSkill(team(),'charisma').toFixed(0)} / 100 · Once every 7 league days.</p>`:''}`)};
const rosterBeforeMorale=roster;roster=function(free=false){const body=rosterBeforeMorale(free);if(free||rosterTeamId!==controlledTeamId())return body;const chemistry=teamChemistry(team());return body+`<section class="panel"><div class="panelhead"><h2>Rotation & locker room</h2><span>Chemistry ${chemistry.score} / 100</span></div><div class="note"><p>Manage your depth chart, planned lineups and 240 minutes in Rotations.</p><div class="actions"><button class="primary" onclick="go('Rotations')">Manage rotations →</button><button onclick="holdMoraleMeeting()" ${moraleStamp()-(state.lastTeamMeeting??-10000000)<7?'disabled':''}>Hold team meeting</button></div><p>Coach conversations: ${Math.round(coachMeetingChance(team())*100)}% success · 7-day cooldown.</p></div></section>`};
function updateRotationTotal(form){document.getElementById('rotation-total').textContent=team().roster.reduce((s,p)=>s+Number(form.elements['min_'+p.id].value||0),0)+' / 240 minutes'}
async function saveRotation(event){event.preventDefault();const values=team().roster.map(p=>Number(event.target.elements['min_'+p.id].value));const error=document.getElementById('rotation-error');if(values.some(n=>!Number.isInteger(n)||n<0||n>48)||values.reduce((s,n)=>s+n,0)!==240){error.textContent='Use whole minutes from 0 to 48, totaling exactly 240.';return}const previous=team().roster.map(p=>p.rotationMinutes);team().roster.forEach((p,i)=>p.rotationMinutes=values[i]);if(!await save()){team().roster.forEach((p,i)=>{if(previous[i]===undefined)delete p.rotationMinutes;else p.rotationMinutes=previous[i]});error.textContent='Could not save the rotation. Try again.';return}render();toast('Rotation saved. Morale and game usage updated.')}
async function holdMoraleMeeting(id){const c=id===undefined?null:playerContext(id);if(id!==undefined&&!c?.own)return;const last=c?c.p.lastTalk:state.lastTeamMeeting,stamp=moraleStamp();if(stamp-(last??-10000000)<7)return toast('Wait 7 league days between meetings.');const players=c?[c.p]:team().roster;const previous=players.map(p=>({m:p.moraleAdjustment,t:p.lastTalk,d:p.dissatisfaction?copy(p.dissatisfaction):undefined}));if(c)c.p.lastTalk=stamp;else state.lastTeamMeeting=stamp;const success=Math.random()<coachMeetingChance(team());for(const p of players)if(success)p.moraleAdjustment=Math.min(30,(p.moraleAdjustment||0)+(c?12:6));if(typeof dissatisfactionRecord==='function')for(const p of players){const d=dissatisfactionRecord(p,team());d.attempts.push({kind:'coach_conversation',stamp:dissatisfactionStamp(),year:state.year,day:state.day});d.attempts=d.attempts.slice(-20);}if(!await save()){players.forEach((p,i)=>{p.moraleAdjustment=previous[i].m;p.lastTalk=previous[i].t;p.dissatisfaction=previous[i].d});if(!c)state.lastTeamMeeting=last;toast('Could not save the meeting. Try again.');return}render();if(c)profile(id);toast(success?'The conversation helped. Morale has improved temporarily.':'The concerns remain. No morale improvement this time.')}
function updateMoraleAfterGame(club,won){for(const p of club.roster)dissatisfactionAfterGame(p,club,moraleDetails(p,club).score)}
const moralePreviousPlay=play;play=function(a,b,stage){const result=moralePreviousPlay(a,b,stage);updateMoraleAfterGame(state.teams[a],result.winner===a);updateMoraleAfterGame(state.teams[b],result.winner===b);return result};
function resetPlayerSituation(p){p.lowMoraleGames=0;p.tradeDemand=false;delete p.rotationMinutes;delete p.lastTalk}
